import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

PINS = [2, 3, 4]
DELAY_SECONDS = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            dev = OutputDevice(pin)
            devices.append(dev)
            print(f"GPIO {pin} configured as output (BCM).")
    except GPIODeviceError as exc:
        print(f"Error: unable to initialize GPIO device: {exc}", file=sys.stderr)
        for dev in devices:
            try:
                dev.close()
            except GPIODeviceClosed:
                pass
        sys.exit(1)

    try:
        while _running:
            for dev in devices:
                try:
                    state = dev.value
                    print(f"GPIO {dev.pin.number} -> {'HIGH' if state else 'LOW'}")
                except GPIODeviceClosed:
                    print(f"GPIO {dev.pin.number} is closed.", file=sys.stderr)
            time.sleep(DELAY_SECONDS)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        for dev in devices:
            try:
                dev.close()
            except GPIODeviceClosed:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 is not installed. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
WHO_AM_I_EXPECTED = 0x68

running = True


def handle_signal(signum, frame):
    global running
    running = False


def init_mpu6050(bus):
    try:
        who = bus.read_byte_data(MPU6050_ADDR, WHO_AM_I)
        if who != WHO_AM_I_EXPECTED:
            print(f"Error: device at 0x{MPU6050_ADDR:02X} returned WHO_AM_I=0x{who:02X} (expected 0x{WHO_AM_I_EXPECTED:02X})", file=sys.stderr)
            return False
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
        time.sleep(0.1)
        return True
    except OSError as e:
        print(f"Error: failed to communicate with MPU6050 at 0x{MPU6050_ADDR:02X}: {e}", file=sys.stderr)
        return False


def read_raw(bus):
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, 0x3B, 14)
        return (data[0] << 8) | data[1], (data[2] << 8) | data[3], (data[4] << 8) | data[5]
    except OSError as e:
        print(f"Error: I2C read failed: {e}", file=sys.stderr)
        return None


def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    if not init_mpu6050(bus):
        bus.close()
        sys.exit(1)

    try:
        while running:
            result = read_raw(bus)
            if result is not None:
                ax, ay, az = result
                print(f"Accel X: {ax}, Y: {ay}, Z: {az}")
            time.sleep(0.01)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

import time
import signal
import sys
from gpiozero import PWMOutputDevice

PWM_PINS = [1, 2, 3, 4]
PWM_FREQUENCY = 1000.0
SLEEP_DURATION = 0.1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _check_reading(reading):
    if not isinstance(reading, (int, float)):
        return False
    if reading < 0.0 or reading > 1.0:
        return False
    return True

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pwm_devices = []
    try:
        for pin in PWM_PINS:
            try:
                dev = PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0.0)
                pwm_devices.append(dev)
            except Exception as exc:
                print(f"Failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                raise

        while _running:
            for idx, pin in enumerate(PWM_PINS):
                reading = idx / (len(PWM_PINS) - 1) if _running else None
                if not _check_reading(reading):
                    print(f"Invalid reading {reading} for GPIO {pin}; skipping.", file=sys.stderr)
                    continue
                try:
                    pwm_devices[idx].value = reading
                    print(f"GPIO {pin} set to {reading:.4f}")
                except Exception as exc:
                    print(f"Error setting PWM on GPIO {pin}: {exc}", file=sys.stderr)
            time.sleep(SLEEP_DURATION)

    except Exception as exc:
        print(f"An error occurred: {exc}", file=sys.stderr)
    finally:
        for dev in pwm_devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

