import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUD = 9600
TIMEOUT = 2
POLL_INTERVAL = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _validate_reading(raw: bytes) -> bool:
    """Return True only if the reading is a non-empty string."""
    if not raw:
        return False
    try:
        text = raw.decode("ascii", errors="replace").strip()
    except Exception:
        return False
    return bool(text)


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        ser = serial.Serial(PORT, BAUD, timeout=TIMEOUT)
        print(f"Opened {PORT} @ {BAUD} baud")
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Error: unexpected failure opening {PORT}: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                break
            except Exception as exc:
                print(f"Error: unexpected read failure: {exc}", file=sys.stderr)
                break

            if not _validate_reading(raw):
                continue

            line = raw.decode("ascii", errors="replace").strip()
            print(f"Received: {line}")

            time.sleep(POLL_INTERVAL)
    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
                print("Serial port closed.")
            except Exception as exc:
                print(f"Warning: error closing serial port: {exc}", file=sys.stderr)

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import serial

PORT = '/dev/serial0'
BAUD = 9600
TIMEOUT = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_sensor_data(ser):
    """Read one line from the serial port and validate it as a 3-byte payload."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        data = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None

    if not data or len(data) < 3:
        return None

    try:
        a, b, c = data[0], data[1], data[2]
        if not all(ord(c) >= 32 and ord(c) <= 126 for c in (a, b, c)):
            return None
    except Exception:
        return None

    return data

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(PORT, BAUD, timeout=TIMEOUT)
    except serial.SerialException as exc:
        print(f"Failed to open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            reading = read_sensor_data(ser)
            if reading is not None:
                print(f"Sensor Reading: {reading}")
            else:
                print("No valid reading received.", file=sys.stderr)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

