import signal
import sys
import time

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 is not installed. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
WHO_AM_I_EXPECTED = 0x68

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def init_mpu6050(bus):
    """Initialize the MPU6050: verify WHO_AM_I and wake up."""
    try:
        who = bus.read_byte_data(MPU6050_ADDR, WHO_AM_I)
    except OSError as exc:
        print(f"Error: device not responding at 0x{MPU6050_ADDR:02X}: {exc}", file=sys.stderr)
        return False

    if who != WHO_AM_I_EXPECTED:
        print(f"Error: device at 0x{MPU6050_ADDR:02X} returned WHO_AM_I=0x{who:02X} (expected 0x{WHO_AM_I_EXPECTED:02X})", file=sys.stderr)
        return False

    try:
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
    except OSError as exc:
        print(f"Error: failed to wake MPU6050: {exc}", file=sys.stderr)
        return False

    time.sleep(0.1)
    return True


def read_raw(bus):
    """Read raw accelerometer and gyroscope data (16-bit signed)."""
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, 0x3B, 14)
    except OSError as exc:
        print(f"Error: I2C read failed: {exc}", file=sys.stderr)
        return None

    ax = (data[0] << 8) | data[1]
    ay = (data[2] << 8) | data[3]
    az = (data[4] << 8) | data[5]
    gx = (data[8] << 8) | data[9]
    gy = (data[10] << 8) | data[11]
    gz = (data[12] << 8) | data[13]

    if ax >= 0x8000:
        ax -= 0x10000
    if ay >= 0x8000:
        ay -= 0x10000
    if az >= 0x8000:
        az -= 0x10000
    if gx >= 0x8000:
        gx -= 0x10000
    if gy >= 0x8000:
        gy -= 0x10000
    if gz >= 0x8000:
        gz -= 0x10000

    return ax, ay, az, gx, gy, gz


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        if not init_mpu6050(bus):
            sys.exit(1)

        raw = read_raw(bus)
        if raw is None:
            sys.exit(1)

        ax, ay, az, gx, gy, gz = raw
        print(f"Accel X: {ax}, Y: {ay}, Z: {az}")
        print(f"Gyro  X: {gx}, Y: {gy}, Z: {gz}")
    finally:
        bus.close()


if __name__ == "__main__":
    main()

