import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUD = 9600
TIMEOUT_S = 1
READ_COUNT = 3
READ_INTERVAL_S = 1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(PORT, BAUD, timeout=TIMEOUT_S)
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        return 1

    try:
        for i in range(READ_COUNT):
            if not _running:
                print("Interrupted by signal; exiting early.", file=sys.stderr)
                break

            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                return 1

            if not raw:
                print(f"Reading {i + 1}/{READ_COUNT}: timeout - no data received")
            else:
                text = raw.decode("utf-8", errors="replace").strip()
                print(f"Reading {i + 1}/{READ_COUNT}: {text}")

            if i < READ_COUNT - 1:
                time.sleep(READ_INTERVAL_S)
    finally:
        try:
            ser.close()
        except Exception:
            pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time
import logging

from RPLCD.i2c import CharLCD

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")

LCD_ADDR = 0x27
LCD_COLS = 16
LCD_ROWS = 2
POLL_INTERVAL = 5.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _check_value(value):
    if not isinstance(value, (int, float)):
        return False
    if value < -32768 or value > 32767:
        return False
    return True


def _write_to_lcd(lcd, value):
    if not _check_value(value):
        logging.error("Invalid value: %r", value)
        return False
    try:
        lcd.clear()
        lcd.write_string(f"Value: {value}")
        return True
    except OSError as exc:
        logging.error("LCD I/O error: %s", exc)
        return False
    except Exception as exc:
        logging.error("Unexpected LCD error: %s", exc)
        return False


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        lcd = CharLCD(i2c_expander='PCF8574', address=LCD_ADDR, port=1,
                      cols=LCD_COLS, rows=LCD_ROWS, dotsize=8,
                      charmap='A02', auto_linebreaks=True)
    except OSError as exc:
        logging.error("Failed to initialize LCD at 0x%02X: %s", LCD_ADDR, exc)
        sys.exit(1)
    except Exception as exc:
        logging.error("Unexpected LCD init error: %s", exc)
        sys.exit(1)

    try:
        while _running:
            _write_to_lcd(lcd, 42)
            time.sleep(POLL_INTERVAL)
    finally:
        try:
            lcd.clear()
            lcd.close()
        except Exception:
            pass
        logging.info("LCD released. Exiting.")


if __name__ == "__main__":
    main()

