            for dev in devices:
                try:
                    dev.off()
                except GPIODeviceClosed:
                    print(f"Error: device on pin {dev.pin} was closed unexpectedly", file=sys.stderr)
                    raise
            print(f"GPIO {PINS} set LOW")
