import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PWM_PINS = [4, 17, 22, 27]
SLEEP_INTERVAL = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _check_reading(value):
    if value is None:
        return False
    if not isinstance(value, (int, float)):
        return False
    if not 0.0 <= value <= 1.0:
        return False
    return True


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            dev = PWMOutputDevice(pin)
            dev.value = 0.0
            devices.append(dev)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error initializing PWM on GPIO {pin}: {exc}", file=sys.stderr)
        for dev in devices:
            dev.close()
        return 1

    try:
        while _running:
            for dev in devices:
                try:
                    value = dev.value
                except (GPIOZeroError, GPIODeviceError) as exc:
                    print(f"Error reading PWM value on GPIO {dev.pin}: {exc}", file=sys.stderr)
                    continue

                if not _check_reading(value):
                    print(f"Invalid PWM value: {value}", file=sys.stderr)
                    continue

                print(f"GPIO {dev.pin} PWM value: {value:.4f}")

            time.sleep(SLEEP_INTERVAL)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

