import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

PCA9685_ADDR = 0x40
I2C_BUS = 1
READ_INTERVAL = 0.15

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _read_word(bus, addr, reg):
    write_msg = i2c_msg.write(addr, [reg])
    read_msg = i2c_msg.read(addr, 2)
    bus.i2c_rdwr(write_msg, read_msg)
    data = list(read_msg)
    if len(data) < 2:
        raise IOError(f"Short read at register 0x{reg:02X}")
    return (data[0] << 8) | data[1]

def read_pca9685(bus, addr):
    try:
        status = _read_word(bus, addr, 0x00)
        if status & 0x80:
            raise IOError(f"Device reported error bit (status=0x{status:04X})")
        return _read_word(bus, addr, 0x06)
    except IOError as e:
        print(f"Error reading from PCA9685: {e}", file=sys.stderr)
        return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except IOError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            reading = read_pca9685(bus, PCA9685_ADDR)
            if reading is not None:
                print(f"Measurement: {reading}")
            time.sleep(READ_INTERVAL)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

