SLEEP_INTERVAL = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _check_reading(reading):
    if not isinstance(reading, (int, float)):
        return False
    if reading < 0 or reading > 100:
        return False
    return True

def _apply_pwm(pin, value, devices):
    if not _check_reading(value):
        print(f"Invalid reading: {value} for pin {pin}")
        return
    try:
        devices[pin].value = value / 100.0
        print(f"Pin {pin} set to {value}%")
    except Exception as e:
        print(f"Error setting pin {pin}: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = {}
    try:
        for pin in PWM_PINS:
            devices[pin] = PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0)
        print("PWM output devices initialized.")

        while _running:
            for pin in PWM_PINS:
                _apply_pwm(pin, 50, devices)
            time.sleep(SLEEP_INTERVAL)

    except Exception as e:
        print(f"Initialization error: {e}")
    finally:
        for dev in devices.values():
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

