    sys.exit(1)

I2C_BUS = 1
PCF8574_ADDR = 0x27
READ_INTERVAL = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_pcf8574(bus, addr):
    """Read a single byte from the PCF8574. Returns int or None on error."""
    try:
        msg = i2c_msg.write(addr, [0x00])
        bus.i2c_rdwr(msg)
        return int(msg.buf[0])
    except OSError:
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            value = read_pcf8574(bus, PCF8574_ADDR)
            if value is not None:
                print(f"PCF8574 @ 0x{PCF8574_ADDR:02X}: 0x{value:02X}")
            else:
                print(f"PCF8574 @ 0x{PCF8574_ADDR:02X}: read failed (device may be absent)")
            time.sleep(READ_INTERVAL)
    finally:
        if bus is not None:
            bus.close()
        print("Program terminated.")


