import time
import signal
import sys
import board
import adafruit_dht

PIN = board.D22
MAX_RETRIES = 3
RETRY_DELAY = 0.5
CYCLES = 2
INTERVAL = 3.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_dht22(sensor):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            t = sensor.temperature
            h = sensor.humidity
            if t is None or h is None:
                raise RuntimeError("Sensor returned None")
            return t, h
        except RuntimeError as e:
            print(f"  [attempt {attempt}/{MAX_RETRIES}] {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    return None, None

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        sensor = adafruit_dht.DHT22(PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on GPIO 22: {e}")
        sys.exit(1)

    try:
        for cycle in range(1, CYCLES + 1):
            if not _running:
                break
            print(f"Cycle {cycle}/{CYCLES}")
            t, h = read_dht22(sensor)
            if t is not None and h is not None:
                print(f"  Temperature: {t:.1f} C")
                print(f"  Humidity:    {h:.1f} %")
            else:
                print("  [ERROR] Failed to retrieve valid data after retries.")
            if cycle < CYCLES and _running:
                time.sleep(INTERVAL)
    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Program finished.")

if __name__ == "__main__":
    main()

