                    pwm.value = duty
                    print(f"GPIO {PWM_PIN} -> duty={duty:.2f}")
                except DeviceClosed:
                    print("Error: PWM device closed unexpectedly.", file=sys.stderr)
                    sys.exit(1)
                except Exception as exc:
                    print(f"Error: failed to set duty {duty}: {exc}", file=sys.stderr)
                    sys.exit(1)
            if not _running:
