import time
import signal
import sys
import board
import busio
from adafruit_mcp3xxx import MCP3008
from adafruit_mcp3xxx.analog_in import AnalogIn

# Global handle so the signal handler can release the device.
_adc = None
_running = True


def _cleanup():
    """Release hardware resources exactly once."""
    global _adc
    if _adc is not None:
        try:
            _adc.deinit()
        except Exception:
            pass
        _adc = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _read_channel(adc, channel):
    """Return a 10-bit reading, or None on failure / bad data."""
    try:
        chan = AnalogIn(adc, channel)
    except Exception as exc:
        print(f"Error: failed to configure channel {channel}: {exc}", file=sys.stderr)
        return None

    try:
        value = chan.value
    except Exception as exc:
        print(f"Error: failed to read channel {channel}: {exc}", file=sys.stderr)
        return None

    # Sanity-check: 0-1023 is the valid 10-bit range.
    if not (0 <= value <= 1023):
        print(f"Error: channel {channel} returned out-of-range value {value}", file=sys.stderr)
        return None

    return value


def main():
    global _adc

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize I2C bus and MCP3008.
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error: failed to initialize I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _adc = MCP3008(i2c, address=0)
    except Exception as exc:
        print(f"Error: MCP3008 not found at address 0x00: {exc}", file=sys.stderr)
        sys.exit(1)

    # Sample 12 readings, one every 0.5 s.
    readings_taken = 0
    while _running and readings_taken < 12:
        value = _read_channel(_adc, 0)
        if value is not None:
            print(f"ADC Channel 0: {value}")
            readings_taken += 1
        else:
            readings_taken = 0  # reset counter on a bad reading

        if _running and readings_taken < 12:
            time.sleep(0.5)

    _cleanup()
    print("ADC sampling complete.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

# TSL2561 constants
TSL2561_ADDR = 0x39
TSL2561_CMD = 0x80
TSL2561_REG_CONTROL = 0x00
TLS2561_REG_TIMING = 0x01
TSL2561_REG_DATA0LOW = 0x0C
TSL2561_REG_DATA1LOW = 0x0E

TSL2561_CMD_POWERON = 0x03
TSL2561_CMD_POWEROFF = 0x00
TSL2561_CMD_RESET = 0x01

TSL2561_INTEGRATIONTIME_13MS = 0x00
TSL2561_INTEGRATIONTIME_101MS = 0x01

TSL2561_GAIN_LOW = 0x00
TSL2561_GAIN_HIGH = 0x10

TSL2561_OK = 0
TSL2561_ERR_DEVNOTFOUND = -1
TSL2561_ERR_INVALIDPARAM = -2
TSL2561_ERR_CHIPNOTDETECTED = -3
TSL2561_ERR_NODATA = -4

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    msg = i2c_msg.write(TSL2561_ADDR, [TSL2561_CMD | reg, value])
    bus.i2c_rdwr(msg)


def _read_reg(bus, reg):
    write_msg = i2c_msg.write(TSL2561_ADDR, [TSL2561_CMD | reg])
    read_msg = i2c_msg.read(TSL2561_ADDR, 1)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)[0]


def _read_word(bus, reg):
    write_msg = i2c_msg.write(TSL2561_ADDR, [TSL2561_CMD | reg])
    read_msg = i2c_msg.read(TSL2561_ADDR, 2)
    bus.i2c_rdwr(write_msg, read_msg)
    lo, hi = list(read_msg)
    return (hi << 8) | lo


def _read_channel0(bus):
    return _read_word(bus, TSL2561_REG_DATA0LOW)


def _read_channel1(bus):
    return _read_word(bus, TSL2561_REG_DATA1LOW)


def _read_tsl2561(bus, gain, integration_time):
    _write_reg(bus, TSL2561_REG_CONTROL, TSL2561_CMD_POWERON)

    if integration_time == TSL2561_INTEGRATIONTIME_13MS:
        atime = 0x00
    elif integration_time == TSL2561_INTEGRATIONTIME_101MS:
        atime = 0x01
    else:
        raise ValueError("Invalid integration time")

    if gain == TSL2561_GAIN_LOW:
        again = 0x00
    elif gain == TSL2561_GAIN_HIGH:
        again = 0x10
    else:
        raise ValueError("Invalid gain")

    _write_reg(bus, TLS2561_REG_TIMING, atime | again)

    time.sleep(0.12 if integration_time == TSL2561_INTEGRATIONTIME_13MS else 0.2)

    ch0 = _read_channel0(bus)
    ch1 = _read_channel1(bus)

    if ch0 == 0 or ch1 == 0:
        raise ValueError("Invalid data (zero count)")

    _write_reg(bus, TSL2561_REG_CONTROL, TSL2561_CMD_POWEROFF)
    return ch0, ch1


def _check_device(bus):
    try:
        _read_reg(bus, TSL2561_REG_CONTROL)
        return True
    except OSError:
        return False


def _init_device(bus):
    _write_reg(bus, TSL2561_REG_CONTROL, TSL2561_CMD_RESET)
    time.sleep(0.01)
    _write_reg(bus, TSL2561_REG_CONTROL, TSL2561_CMD_POWERON)
    time.sleep(0.01)
    _write_reg(bus, TLS2561_REG_TIMING, TSL2561_INTEGRATIONTIME_101MS | TSL2561_GAIN_LOW)
    time.sleep(0.01)


def read_tsl2561(bus, gain=TSL2561_GAIN_LOW, integration_time=TSL2561_INTEGRATIONTIME_101MS):
    if not _check_device(bus):
        return TSL2561_ERR_DEVNOTFOUND
    try:
        ch0, ch1 = _read_tsl2561(bus, gain, integration_time)
        return ch0, ch1
    except OSError:
        return TSL2561_ERR_DEVNOTFOUND
    except ValueError:
        return TSL2561_ERR_NODATA


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    if not _check_device(bus):
        print("Error: no device found at address 0x39 on bus 1", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        _init_device(bus)
    except OSError as e:
        print(f"Error: failed to initialize TSL2561: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        while _running:
            result = read_tsl2561(bus)
            if result == TSL2561_ERR_DEVNOTFOUND:
                print("Error: device not found", file=sys.stderr)
                break
            elif result == TSL2561_ERR_NODATA:
                print("Error: invalid data (zero count)", file=sys.stderr)
                break
            elif result == TSL2561_ERR_CHIPNOTDETECTED:
                print("Error: chip not detected", file=sys.stderr)
                break
            else:
                ch0, ch1 = result
                print(f"Channel 0: {ch0}, Channel 1: {ch1}")
            time.sleep(1)
    finally:
        if bus is not None:
            try:
                _write_reg(bus, TSL2561_REG_CONTROL, TSL2561_CMD_POWEROFF)
            except OSError:
                pass
            bus.close()


if __name__ == "__main__":
    main()

import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUD = 9600
TIMEOUT = 1.0
POLL_INTERVAL = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _validate_reading(raw: bytes) -> bool:
    """Return True only if the reading is a non-empty string."""
    if not raw:
        return False
    try:
        text = raw.decode("ascii", errors="replace").strip()
    except Exception:
        return False
    return bool(text)


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        ser = serial.Serial(PORT, BAUD, timeout=TIMEOUT)
        print(f"Opened {PORT} @ {BAUD} baud", file=sys.stderr)

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Serial read error: {exc}", file=sys.stderr)
                break

            if not _validate_reading(raw):
                continue

            text = raw.decode("ascii", errors="replace").strip()
            print(text)

            time.sleep(POLL_INTERVAL)

    except serial.SerialException as exc:
        print(f"Error opening {PORT}: {exc}", file=sys.stderr)
        return 1
    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

