import signal
import sys
import time

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 is not installed. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
WHO_AM_I = 0x75
WHO_AM_I_EXPECTED = 0x68
ACCEL_XOUT_H = 0x3B
ACCEL_YOUT_H = 0x3D
ACCEL_ZOUT_H = 0x3F
GYRO_XOUT_H = 0x43
GYRO_YOUT_H = 0x45
GYRO_ZOUT_H = 0x47

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _read_word(bus, addr, reg):
    """Read a signed 16-bit word from two consecutive registers."""
    high = bus.read_byte_data(addr, reg)
    low = bus.read_byte_data(addr, reg + 1)
    val = (high << 8) | low
    if val >= 0x8000:
        val -= 0x10000
    return val


def _read_raw(bus, addr, reg):
    """Read a raw 16-bit value from two consecutive registers."""
    high = bus.read_byte_data(addr, reg)
    low = bus.read_byte_data(addr, reg + 1)
    return (high << 8) | low


def _read_axis(bus, addr, reg):
    """Read an axis value and return it in signed 16-bit range."""
    return _read_word(bus, addr, reg)


def _read_temperature(bus, addr):
    """Read temperature from the temperature register."""
    return _read_word(bus, addr, 0x41)


def _read_gyro(bus, addr):
    """Read all three gyroscope axes."""
    return _read_axis(bus, addr, GYRO_XOUT_H), _read_axis(bus, addr, GYRO_YOUT_H), _read_axis(bus, addr, GYRO_ZOUT_H)


def _read_accel(bus, addr):
    """Read all three accelerometer axes."""
    return _read_axis(bus, addr, ACCEL_XOUT_H), _read_axis(bus, addr, ACCEL_YOUT_H), _read_axis(bus, addr, ACCEL_ZOUT_H)


def _init_sensor(bus, addr):
    """Initialize the MPU6050: verify identity and wake up."""
    who = bus.read_byte_data(addr, WHO_AM_I)
    if who != WHO_AM_I_EXPECTED:
        raise RuntimeError(f"MPU6050 not found at 0x{addr:02X} (WHO_AM_I=0x{who:02X})")
    bus.write_byte_data(addr, PWR_MGMT_1, 0x00)
    time.sleep(0.1)


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        _init_sensor(bus, MPU6050_ADDR)
    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        while _running:
            try:
                ax, ay, az = _read_accel(bus, MPU6050_ADDR)
                gx, gy, gz = _read_gyro(bus, MPU6050_ADDR)
                temp = _read_temperature(bus, MPU6050_ADDR)

                print(f"Accel: X={ax:+6d} Y={ay:+6d} Z={az:+6d}  "
                      f"Gyro: X={gx:+6d} Y={gy:+6d} Z={gz:+6d}  "
                      f"Temp: {temp:+6d} C")
                sys.stdout.flush()

            except OSError as e:
                print(f"Error: I2C communication failed: {e}", file=sys.stderr)
                break
            except Exception as e:
                print(f"Error: unexpected read failure: {e}", file=sys.stderr)
                break

            time.sleep(0.1)
    finally:
        if bus is not None:
            bus.close()


if __name__ == "__main__":
    main()

