import time
import signal
import sys
from gpiozero import PWMOutputDevice

PCA9685_ADDRESS = 0x40
PCA9685_LED0_ON_L = 0x06
PCA9685_LED0_ON_H = 0x07
PCA9685_LED0_OFF_L = 0x08
PCA9685_LED0_OFF_H = 0x09

PWM_FREQUENCY = 1000
SLEEP_DURATION = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _write_reg(dev, reg, value):
    """Write a single byte to a register with error handling."""
    try:
        dev.i2c_write_byte_data(PCA9685_ADDRESS, reg, value)
    except Exception as e:
        print(f"Error writing to register 0x{reg:02X}: {e}", file=sys.stderr)
        raise

def _read_reg(dev, reg):
    """Read a single byte from a register with error handling."""
    try:
        return dev.i2c_read_byte_data(PCA9685_ADDRESS, reg)
    except Exception as e:
        print(f"Error reading from register 0x{reg:02X}: {e}", file=sys.stderr)
        raise

def _check_device(dev):
    """Verify the device is responding by reading the LED0 ON_L register."""
    try:
        _read_reg(dev, PCA9685_LED0_ON_L)
        return True
    except Exception:
        return False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(
            pin=0,
            frequency=PWM_FREQUENCY,
            initial_value=0.0,
        )
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO 0: {e}", file=sys.stderr)
        sys.exit(1)

    if not _check_device(pwm):
        print("Error: No PCA9685 detected at address 0x40 on I2C bus.", file=sys.stderr)
        pwm.close()
        sys.exit(1)

    try:
        while _running:
            try:
                on_l = _read_reg(pwm, PCA9685_LED0_ON_L)
                on_h = _read_reg(pwm, PCA9685_LED0_ON_H)
                off_l = _read_reg(pwm, PCA9685_LED0_OFF_L)
                off_h = _read_reg(pwm, PCA9685_LED0_OFF_H)

                state = (on_l, on_h, off_l, off_h)
                print(f"State: ON_L=0x{on_l:02X}, ON_H=0x{on_h:02X}, OFF_L=0x{off_l:02X}, OFF_H=0x{off_h:02X}")
            except Exception:
                print("Failed to read state from PCA9685.", file=sys.stderr)

            time.sleep(SLEEP_DURATION)
    finally:
        pwm.close()
        print("PWM device closed.")

if __name__ == "__main__":
    main()

