import time
import signal
import sys
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]
PWM_FREQUENCY = 1000
SLEEP_DURATION = 1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _check_value(value):
    if not isinstance(value, (int, float)):
        return False
    if value < 0 or value > 1:
        return False
    return True

def _set_pwm(pin, value, devices):
    if pin not in devices:
        return
    dev = devices[pin]
    if not _check_value(value):
        print(f"Invalid value {value} for pin {pin}; skipping.")
        return
    try:
        dev.value = value
        print(f"Pin {pin} set to {value}")
    except DeviceClosed:
        print(f"Pin {pin} device closed; skipping.")
    except GPIOZeroError as e:
        print(f"Error setting pin {pin}: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = {}
    try:
        for pin in PWM_PINS:
            try:
                devices[pin] = PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0)
            except GPIOZeroError as e:
                print(f"Failed to initialize PWM on GPIO {pin}: {e}")
                sys.exit(1)
    except Exception as e:
        print(f"Unexpected initialization error: {e}")
        sys.exit(1)

    try:
        while _running:
            for pin in PWM_PINS:
                _set_pwm(pin, 0.5, devices)
            time.sleep(SLEEP_DURATION)
    except Exception as e:
        print(f"Runtime error: {e}")
        sys.exit(1)
    finally:
        for pin, dev in devices.items():
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

