import time
import signal
import sys
import board
import adafruit_dht

# DHT22 data pin connected to GPIO 4 (BCM) -> board.D4
DHT_PIN = board.D4
READ_INTERVAL = 60  # seconds between readings
NUM_READINGS = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO 4: {exc}", file=sys.stderr)
        sys.exit(1)

    readings_taken = 0
    try:
        while _running and readings_taken < NUM_READINGS:
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity

                if temperature is None or humidity is None:
                    print("Sensor returned None for temperature or humidity.")
                else:
                    print(f"Reading {readings_taken + 1}: Temperature = {temperature:.1f} C, Humidity = {humidity:.1f} %")
                    readings_taken += 1

            except RuntimeError as exc:
                # DHT22 checksum or timing errors are common; report and continue
                print(f"Sensor read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Unexpected error during read: {exc}", file=sys.stderr)

            if _running and readings_taken < NUM_READINGS:
                # Interruptible sleep so Ctrl-C exits promptly
                sleep_end = time.monotonic() + READ_INTERVAL
                while _running and time.monotonic() < sleep_end:
                    time.sleep(0.1)
    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Program finished.")

if __name__ == "__main__":
    main()

